-- Idle és aktív worker folyamatok belső health állapota; nem tartalmaz secretet vagy claim tokent.
CREATE TABLE worker_runtime_health (worker_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, process_id INT UNSIGNED NOT NULL, hostname VARCHAR(255) NOT NULL, state VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'starting', started_at DATETIME(6) NOT NULL, heartbeat_at DATETIME(6) NOT NULL, last_article_claim_at DATETIME(6) NULL, last_article_completion_at DATETIME(6) NULL, shutdown_at DATETIME(6) NULL, updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (worker_id), KEY idx_worker_health_state_heartbeat (state, heartbeat_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
